#!/usr/bin/env python3
# luxarch:targeted-guard-run hook v2 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny a full luxarch scan piped into a filter: check one rule or one file with `--rule`.

`luxarch --rule <id>` runs only the matching rules, and `--path <file>` narrows the output to one
file. A full scan (`make arch`, or the image with no `--rule`) takes minutes on a large repo, and
filtering its output with grep, head or tail to read one rule or one file spends all of that to
throw most of it away. The whole repo's per-rule counts are in `.luxarch-status.json`
(`make status`).

PreToolUse(Bash): deny a pipeline whose first stage runs a full luxarch scan and whose later stage
is a text filter. A full scan run on its own or saved to a file, `make status`, a `--rule`,
`--sweep` or `--plan` run, the image's non-scan modes (`--doc`, `--emit`, `--changelog`, ...), an
`--entrypoint` override and a make dry run all pass. A tool call whose event cannot be read is
denied.
"""

from __future__ import annotations

import re
import shlex
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import (  # sibling helper, loaded by path
    command_text,
    guarded,
    load_event,
    text_field,
    tool_input,
)

# The luxarch image, by registry ref, local tag or digest, or the variable that names it.
_IMAGE = re.compile(
    r"^(?:[\w.:-]+/)*luxarch(?::[\w.-]+)?(?:@sha256:\w+)?$"
    r"|^\$\{?LUXARCH(?:_IMAGE)?\}?$|^\$\(LUXARCH(?:_IMAGE)?\)$"
)
# `docker run` options that take no value; every other option takes the next word unless it is
# written `--opt=value`.
_FLAG_ONLY = {
    "--rm",
    "-i",
    "-t",
    "-it",
    "-ti",
    "-d",
    "--detach",
    "--init",
    "--privileged",
    "--read-only",
    "--interactive",
    "--tty",
    "-q",
    "--quiet",
    "--sig-proxy",
    "-P",
    "--publish-all",
    "--no-healthcheck",
    "--oom-kill-disable",
}
# Image arguments that make a run targeted, or not a scan at all.
_NOT_A_FULL_SCAN = {
    "--rule",
    "--sweep",
    "--plan",
    "--emit",
    "--doc",
    "--docs",
    "--playbook",
    "--list-rules",
    "--fleet-versions",
    "--fleet-deps",
    "--changelog",
    "--new-rules",
    "--upgrade",
    "--version",
    "--help",
    "-h",
    "--map",
}
# make options that take the next word as their value, and those that run nothing.
_MAKE_VALUED = {
    "-C",
    "-f",
    "-I",
    "-o",
    "-W",
    "--directory",
    "--file",
    "--makefile",
    "--include-dir",
    "--old-file",
    "--what-if",
    "--assume-old",
    "--assume-new",
}
_MAKE_DRY = {
    "-n",
    "--dry-run",
    "--just-print",
    "--recon",
    "-q",
    "--question",
    "-p",
    "--print-data-base",
}
_LEADERS = {"time", "sudo", "nice", "command", "exec", "env"}
_FILTERS = {
    "grep",
    "egrep",
    "fgrep",
    "rg",
    "ag",
    "awk",
    "sed",
    "perl",
    "head",
    "tail",
    "jq",
    "cut",
    "wc",
    "sort",
    "uniq",
}
_STATEMENT = re.compile(r"&&|\|\||;|\n")
_PIPE = re.compile(r"\|&?")
# A newline that continues the command: after a backslash, or after a pipe, `&&` or `||`.
_CONTINUED = re.compile(r"\\\n|(?<=\|)[ \t]*\n|(?<=&&)[ \t]*\n")


def _words(raw: str) -> list[str]:
    try:
        return shlex.split(raw)
    except ValueError:
        return raw.split()


def _command(words: list[str]) -> list[str]:
    """``words`` from the command word on: env assignments, wrappers and `timeout N` dropped."""
    i = 0
    while i < len(words):
        w = words[i].lstrip("({")
        if not w or w in _LEADERS or re.match(r"^\w+=", w):
            i += 1
        elif w == "timeout":
            i += 2
        elif w == "xargs":
            i += 1
            while i < len(words) and words[i].startswith("-"):
                i += 1
        else:
            return [w, *words[i + 1 :]]
    return []


def _make_runs_arch(args: list[str]) -> bool:
    i = 0
    while i < len(args):
        a = args[i]
        if a in _MAKE_DRY or re.match(r"^-[a-zA-Z]*[nqp][a-zA-Z]*$", a):
            return False
        if a in _MAKE_VALUED:
            i += 2
            continue
        if a.startswith("-") or "=" in a:
            i += 1
            continue
        return a.rstrip(");}") == "arch"
    return False


def _docker_runs_full_scan(args: list[str]) -> bool:
    if args[:1] == ["container"]:
        args = args[1:]
    if args[:1] != ["run"]:
        return False
    i = 1
    while i < len(args):
        a = args[i]
        if a == "--entrypoint" or a.startswith("--entrypoint="):
            return False
        if not a.startswith("-"):
            flags = {r.split("=", 1)[0] for r in args[i + 1 :] if r.startswith("-")}
            return bool(_IMAGE.match(a)) and not flags & _NOT_A_FULL_SCAN
        i += 1 if (a in _FLAG_ONLY or "=" in a) else 2
    return False


def _full_scan(raw: str) -> bool:
    words = _command(_words(raw))
    if not words:
        return False
    head = Path(words[0]).name
    if head == "make":
        return _make_runs_arch(words[1:])
    if head in {"docker", "podman"}:
        return _docker_runs_full_scan(words[1:])
    return False


def _is_filter(raw: str) -> bool:
    words = _command(_words(raw))
    return bool(words) and Path(words[0]).name in _FILTERS


def filtered_full_scan(cmd: str) -> bool:
    """A statement of `cmd` pipes a full luxarch scan into a text filter."""
    joined = _CONTINUED.sub(lambda m: " " * len(m.group(0)), cmd)
    masked = command_text(joined)
    start = 0
    for m in [*_STATEMENT.finditer(masked), None]:
        end = m.start() if m else len(masked)
        stmt_m, stmt_r = masked[start:end], joined[start:end]
        start = m.end() if m else end
        pipes = list(_PIPE.finditer(stmt_m))
        if not pipes:
            continue
        starts = [0, *(p.end() for p in pipes)]
        ends = [*(p.start() for p in pipes), len(stmt_m)]
        stages = [(stmt_m[a:b], stmt_r[a:b]) for a, b in zip(starts, ends, strict=True)]
        if not stages[0][0].strip() or not _full_scan(stages[0][1]):
            continue
        # A stage blanked by the mask (a comment, quoted data) is not a command.
        if any(_is_filter(r) for s, r in stages[1:] if s.strip()):
            return True
    return False


def main() -> int:
    ev = load_event()
    if ev.get("tool_name") != "Bash":
        return 0
    cmd = text_field(tool_input(ev), "command")
    if filtered_full_scan(cmd):
        print(
            "DENIED: a full luxarch scan filtered through grep, head or tail runs every rule "
            "to read one.\n"
            "Run only what you need: `luxarch --rule <id>` (exact or substring, repeatable or "
            "comma-separated) runs only the matching rules, and `--path <file>` narrows the output "
            "to one file. The whole repo's per-rule counts are in `.luxarch-status.json` "
            "(`make status`). A full scan you want to read whole runs without a filter.",
            file=sys.stderr,
        )
        return 2
    return 0


sys.exit(guarded(main, "targeted-guard-run"))
